def comps(G,bg):
    R,C=len(G),len(G[0]); seen=[[False]*C for _ in range(R)]; res=[]
    for r in range(R):
        for c in range(C):
            if G[r][c]!=bg and not seen[r][c]:
                col=G[r][c]; stack=[(r,c)]; cells=[]
                seen[r][c]=True
                while stack:
                    x,y=stack.pop(); cells.append((x,y))
                    for dx,dy in((1,0),(-1,0),(0,1),(0,-1)):
                        a,b=x+dx,y+dy
                        if 0<=a<R and 0<=b<C and not seen[a][b] and G[a][b]==col:
                            seen[a][b]=True; stack.append((a,b))
                res.append((col,cells))
    return res
